cd /Users/sameralzubaidi/Desktop/kids_marketplace_app/p2p-kids-admin && node <<'NODE'
const dotenv = require('dotenv');
const { createClient } = require('@supabase/supabase-js');

dotenv.config({ path: '.env.local', override: true });
const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
const key = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (!url || !key) {
  console.error('Missing NEXT_PUBLIC_SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY');
  process.exit(2);
}

const sb = createClient(url, key);

(async () => {
  const out = {};
  out.env = { url: Boolean(url), key: Boolean(key) };

  const trades = await sb
    .from('trades')
    .select('id,disclaimer_acknowledged,disclaimer_policy_id,disclaimer_acknowledged_at')
    .limit(1);
  out.tradesColumnsCheck = {
    error: trades.error ? trades.error.message : null,
    rows: trades.data ? trades.data.length : null,
  };

  const policies = await sb
    .from('platform_policies')
    .select('id,version,title,status,effective_date')
    .eq('policy_type', 'liability_disclaimer')
    .eq('status', 'published')
    .order('created_at', { ascending: false })
    .limit(1);
  out.publishedPolicy = {
    error: policies.error ? policies.error.message : null,
    rows: policies.data ? policies.data.length : null,
    data: policies.data || null,
  };

  const rpc1 = await sb.rpc('get_current_policy', {
    p_policy_type: 'liability_disclaimer',
  });
  out.rpcGetCurrentPolicy_p_policy_type = {
    error: rpc1.error ? rpc1.error.message : null,
    rows: Array.isArray(rpc1.data) ? rpc1.data.length : null,
  };

  const rpc2 = await sb.rpc('get_current_policy', {
    policy_type: 'liability_disclaimer',
  });
  out.rpcGetCurrentPolicy_policy_type = {
    error: rpc2.error ? rpc2.error.message : null,
    rows: Array.isArray(rpc2.data) ? rpc2.data.length : null,
  };

  const rpc3 = await sb.rpc('acknowledge_trade_disclaimer', {
    p_trade_id: '00000000-0000-0000-0000-000000000001',
    p_disclaimer_policy_id: '00000000-0000-0000-0000-000000000001',
  });
  out.rpcAcknowledgeTradeDisclaimer = {
    error: rpc3.error ? rpc3.error.message : null,
    data: rpc3.data || null,
  };

  const pa = await sb
    .from('policy_acceptances')
    .select('id,user_id,policy_type,policy_version,accepted_at,ip_address,user_agent')
    .eq('policy_type', 'liability_disclaimer')
    .order('accepted_at', { ascending: false })
    .limit(3);
  out.policyAcceptancesRead = {
    error: pa.error ? pa.error.message : null,
    rows: pa.data ? pa.data.length : null,
  };

  console.log(JSON.stringify(out, null, 2));
})();
